1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.repository.OwnerRepository;
5	
6	/**
7	 * City capacity rules for owners. A city can hold at most {@link #CAPACITY} owners; a create that
8	 * would exceed that is rejected (see {@link RejectCityAtCapacity}). A city that already holds
9	 * between {@link #WARNING_THRESHOLD} and {@code CAPACITY - 1} owners is <em>approaching</em>
10	 * capacity, surfaced to callers as {@code capacityWarning}.
11	 *
12	 * <p>The counted population matches {@link RejectCityAtCapacity}: every owner in the repository
13	 * whose {@code city} equals the given city (null-safe, same-city equality as
14	 * {@link AssignMemberId}), soft-deleted owners included.
15	 */
16	public final class CityCapacity {
17	
18	    /** Maximum owners a city may hold; a create that would exceed it is rejected. */
19	    static final int CAPACITY = 50;
20	
21	    /** A city holding at least this many owners (but below {@link #CAPACITY}) is approaching capacity. */
22	    private static final int WARNING_THRESHOLD = 40;
23	
24	    private CityCapacity() {
25	    }
26	
27	    /** The number of owners currently in {@code city}. */
28	    static long count(String city, OwnerRepository ownerRepository) {
29	        return ownerRepository.findAll().stream()
30	                .filter(o -> city == null ? o.getCity() == null : city.equals(o.getCity()))
31	                .count();
32	    }
33	
34	    /**
35	     * Returns true when {@code city} already holds between 40 and 49 owners (approaching the hard
36	     * capacity limit of 50), otherwise false.
37	     */
38	    static boolean warning(String city, OwnerRepository ownerRepository) {
39	        long count = count(city, ownerRepository);
40	        return count >= WARNING_THRESHOLD && count < CAPACITY;
41	    }
42	
43	    /** Convenience for computing the warning from an owner's city. */
44	    static boolean warning(Owner owner, OwnerRepository ownerRepository) {
45	        return warning(owner == null ? null : owner.getCity(), ownerRepository);
46	    }
47	}
